using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

public class ParticleEmissionController : MonoBehaviour
{
	[SerializeField]
	private ParticleSystem[] particles;

	[SerializeField]
	private float[] defaultEmissionRates;

	[SerializeField]
	private float[] defaultBurstCountRates;

	[SerializeField]
	private bool enableDisableVFXAnimation;

	[SerializeField]
	[ShowIf("enableDisableVFXAnimation")]
	private DisableVFXAnimation[] disableVFXAnimations;

	public void SetActive(bool value)
	{
		for (int i = 0; i < particles.Length; i++)
		{
			ParticleSystem.EmissionModule emission = particles[i].emission;
			emission.rateOverTime = (value ? defaultEmissionRates[i] : 0f);
			if (defaultBurstCountRates.Length != 0 && particles[i].emission.burstCount > 0)
			{
				ParticleSystem.Burst burst = particles[i].emission.GetBurst(0);
				float time = burst.time;
				ParticleSystem.MinMaxCurve count = new ParticleSystem.MinMaxCurve(value ? defaultBurstCountRates[i] : 0f);
				int cycleCount = burst.cycleCount;
				float repeatInterval = burst.repeatInterval;
				ParticleSystem.Burst burst2 = new ParticleSystem.Burst(time, count, cycleCount, repeatInterval);
				emission.SetBurst(0, burst2);
			}
		}
		if (!value)
		{
			for (int j = 0; j < disableVFXAnimations.Length; j++)
			{
				disableVFXAnimations[j].DisableVFX();
			}
		}
	}

	public void SetActiveSpecificParticle(ParticleSystem particleSystem, bool value)
	{
		ParticleSystem.EmissionModule emission = particleSystem.emission;
		float num = 0f;
		for (int i = 0; i < particles.Length; i++)
		{
			if (particles[i] == particleSystem)
			{
				num = defaultEmissionRates[i];
			}
		}
		emission.rateOverTime = (value ? num : 0f);
	}

	public void ChangeSpecificParticleEmissionRate(ParticleSystem particleSystem, float value)
	{
		ParticleSystem.EmissionModule emission = particleSystem.emission;
		for (int i = 0; i < particles.Length; i++)
		{
			if (particles[i] == particleSystem)
			{
				emission.rateOverTime = value;
			}
		}
	}

	public void RewindParticles()
	{
		for (int i = 0; i < particles.Length; i++)
		{
			particles[i].Play();
		}
	}

	[Button(null)]
	public void GetParticles()
	{
		particles = base.gameObject.GetComponentsInChildren<ParticleSystem>();
		defaultEmissionRates = new float[particles.Length];
		for (int i = 0; i < particles.Length; i++)
		{
			defaultEmissionRates[i] = particles[i].emission.rateOverTime.constant;
		}
		disableVFXAnimations = base.gameObject.GetComponentsInChildren<DisableVFXAnimation>();
		enableDisableVFXAnimation = disableVFXAnimations.Length != 0;
	}

	[Button(null)]
	public void DisableParticles()
	{
		SetActive(value: false);
	}

	[Button(null)]
	public void EnableParticles()
	{
		SetActive(value: true);
	}

	private void PauseEmission(bool value)
	{
		for (int i = 0; i < particles.Length; i++)
		{
			if (value)
			{
				particles[i].Pause();
			}
			else
			{
				particles[i].Play();
			}
		}
	}

	[Button(null)]
	public void KillCurrentParticles()
	{
		for (int i = 0; i < particles.Length; i++)
		{
			particles[i].Clear();
		}
	}

	[Button(null)]
	private void GetBursts()
	{
		defaultBurstCountRates = new float[particles.Length];
		for (int i = 0; i < particles.Length; i++)
		{
			if (particles[i].emission.burstCount > 0)
			{
				defaultBurstCountRates[i] = particles[i].emission.GetBurst(0).count.constant;
			}
		}
	}

	public void SetActiveEmissionModule(bool value)
	{
		for (int i = 0; i < particles.Length; i++)
		{
			ParticleSystem.EmissionModule emission = particles[i].emission;
			emission.enabled = value;
		}
	}
}
